// --------------------------------------------------------------------------------------------------------------------
// VR Battlegrounds patch 66: приоритет клипа с формой на моторе руки.
// --------------------------------------------------------------------------------------------------------------------
namespace UltimateXR.Haptics
{
    /// <summary>
    ///     VR Battlegrounds patch 66: приоритет клипа с формой (<see cref="UxrHapticClip.Waveform" />). Слышен высший приоритет
    ///     среди звучащих на руке. Значения проекта: Low — «можно» (тихо, может быть непрерывным, под высшими на паузе),
    ///     Normal — физика (отдача, ход механизма, щелчки; одновременные складываются по максимуму), High — отказ и
    ///     предупреждение, Critical — гибель.
    /// </summary>
    public enum UxrHapticPriority
    {
        Low      = 1,
        Normal   = 2,
        High     = 3,
        Critical = 4
    }
}
